function toast(msg){const box=$('#toastStack');if(!box)return;const el=document.createElement('div');el.className='toast';el.textContent=msg;box.append(el);setTimeout(()=>el.remove(),2800)}
function getSharedEvents(){try{return JSON.parse(localStorage.getItem('bombhr-demo-events')||'[]')}catch(e){return []}}
function saveSharedEvents(events){localStorage.setItem('bombhr-demo-events',JSON.stringify(events.slice(0,100)));window.dispatchEvent(new CustomEvent('bombhr-demo-update'))}
function getSharedApprovals(){return getSharedEvents().filter(e=>e.category==='approval'&&e.status==='review')}
function updateSharedApproval(id,status,statusText,rejectReason=''){const events=getSharedEvents(),item=events.find(e=>e.id===id||e.eventId===id);if(!item)return;Object.assign(item,{status,statusText,rejectReason,reviewedAt:new Date().toISOString()});saveSharedEvents(events)}
function getAdminApprovalRecords(){try{return JSON.parse(localStorage.getItem('bombhr-admin-approval-records')||'[]')}catch(e){return []}}
function completeAdminApproval(index,status,note=''){const a=approvals[index],records=getAdminApprovalRecords();records.unshift({id:`DEMO-${index}`,title:a[1],employee:a[2],period:a[3],status,note,reviewer:'林怡君',reviewerId:'AB00001',role:'HR 系統管理者',completedAt:new Date().toLocaleString('zh-TW',{hour12:false})});localStorage.setItem('bombhr-admin-approval-records',JSON.stringify(records));location.hash='approvals';window.dispatchEvent(new HashChangeEvent('hashchange'))}
$('#themeToggle')?.addEventListener('click',()=>{store.set('bombhr-theme',document.documentElement.dataset.theme==='dark'?'light':'dark');applyTheme();toast('已切換顯示模式')});
if($('#loginForm')){
 $('#passwordToggle').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password';$('#passwordToggle').textContent=p.type==='password'?'顯示':'隱藏'};
 $('#helpLink').onclick=e=>{e.preventDefault();toast('請聯絡企業人事管理者重設帳號')};
 $('#loginForm').onsubmit=e=>{e.preventDefault();const c=$('#companyCode').value.trim().toUpperCase(),u=$('#employeeId').value.trim().toUpperCase(),p=$('#password').value;if(c==='ABOMB'&&u==='AB00001'&&p==='bombhr'){sessionStorage.setItem('bombhr-admin','1');location.href='dashboard.html'}else $('#loginError').textContent='公司代碼、員工編號或密碼不正確。請使用上方 Demo 帳號。'};
}
function initAdmin(){
 if(!sessionStorage.getItem('bombhr-admin')) sessionStorage.setItem('bombhr-admin','1');
 const nav=[['WORKSPACE','dashboard','⌂','營運總覽','Dashboard'],['PEOPLE','organization','◇','組織管理','Organization'],['PEOPLE','employees','♙','員工人事','Employees'],['WORKFORCE','attendance','◷','出勤與裝置','Attendance'],['WORKFORCE','scheduling','▦','排班月曆','Scheduling'],['WORKFORCE','approvals','✓','簽核中心','Approvals'],['PAY & GROW','payroll','＄','薪資管理','Payroll'],['PAY & GROW','learning','▱','教育訓練','Learning'],['PAY & GROW','skills','◫','技能矩陣','Skills'],['TALENT','performance','◎','績效管理','Performance'],['TALENT','talent','♢','人才發展','Talent'],['TALENT','recruitment','＋','招募管理','Recruitment'],['INSIGHTS','analytics','⌁','人力分析','Analytics'],['SYSTEM','announcements','♧','公告與待辦','Announcements'],['SYSTEM','permissions','⌘','角色與權限','Permissions'],['SYSTEM','settings','⚙','企業設定','Settings']];
 let group='';$('#mainNav').innerHTML=nav.map(n=>{let h='';if(n[0]!==group){group=n[0];h=`<div class="nav-group">${group}</div>`}return h+`<button class="nav-item" data-route="${n[1]}"><i>${n[2]}</i><span>${n[3]}<small>${n[4]}</small></span></button>`}).join('');
 const titles=Object.fromEntries(nav.map(n=>[n[1],n[3]]));
 window.addEventListener('hashchange',render);$$('[data-route]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.route;$('#sidebar').classList.remove('open')});
 $('#menuBtn').onclick=()=>$('#sidebar').classList.add('open');$('#closeNav').onclick=()=>$('#sidebar').classList.remove('open');
 $('[data-action=logout]',document).onclick=logout;$$('[data-action=logout]').forEach(b=>b.onclick=logout);function logout(){sessionStorage.removeItem('bombhr-admin');location.href='index.html'}
 setupScope();setupNotifications();setupSearch();setupProfile();document.addEventListener('keydown',e=>{if(e.key==='Escape'){$$('.open').forEach(x=>x.classList.remove('open'))}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();openSearch()}});
 document.body.addEventListener('click',globalClick);window.addEventListener('storage',e=>{if(e.key==='bombhr-demo-events')render()});window.addEventListener('bombhr-demo-update',render);render();
 function render(){const route=location.hash.slice(1)||'dashboard';$$('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));$('#pageTitle').textContent=titles[route]||'營運總覽';document.title=`BOMB HR｜${titles[route]||'營運總覽'}`;$('#content').innerHTML=(views[route]||views.dashboard)();bindView(route);$('#content').focus()}
}
const employees=[['林怡君','AB00001','人力資源部','HR 系統管理者','台北總部','在職'],['陳冠宇','AB00118','營運管理部','區域營運主管','台北總部','在職'],['王思涵','AB00231','產品設計部','資深產品設計師','台中據點','在職'],['張育誠','AB00307','資訊技術部','前端工程師','高雄據點','試用期'],['李佳穎','AB00322','財務會計部','薪酬專員','台北總部','在職'],['黃柏翰','AB00341','門市營運部','培訓新人','台中據點','培訓中']];
function getCustomEmployees(){try{return JSON.parse(localStorage.getItem('bombhr-custom-employees')||'[]')}catch(e){return []}}
const enterpriseBankDefaults=[{code:'013',name:'國泰世華銀行',branch:'台北分行',purpose:'員工薪資轉帳',active:true},{code:'822',name:'中國信託銀行',branch:'營業部',purpose:'員工薪資轉帳',active:true},{code:'812',name:'台新銀行',branch:'台北分行',purpose:'員工薪資轉帳',active:true},{code:'808',name:'玉山銀行',branch:'台北分行',purpose:'備用薪轉銀行',active:true},{code:'007',name:'第一銀行',branch:'總行營業部',purpose:'企業付款',active:true}];
function getEnterpriseBanks(){try{return JSON.parse(localStorage.getItem('bombhr-enterprise-banks')||'null')||enterpriseBankDefaults}catch(e){return enterpriseBankDefaults}}
function saveEnterpriseBanks(items){localStorage.setItem('bombhr-enterprise-banks',JSON.stringify(items))}
function getProfilePhotos(){try{return JSON.parse(localStorage.getItem('bombhr-employee-profile-photos')||'{}')}catch(e){return {}}}
function employeeAvatar(id,name){const photo=getProfilePhotos()[id];return `<span class="avatar">${photo?`<img src="${photo}" alt="${name} 大頭照">`:name[0]}</span>`}
function getEmployeeRows(){return [...employees,...getCustomEmployees().map(e=>[e.name,e.employeeId,e.department,e.position,e.location,e.status])]}
function nextEmployeeId(){const nums=getEmployeeRows().map(e=>Number(String(e[1]).replace(/\D/g,''))||0);return `AB${String(Math.max(...nums)+1).padStart(5,'0')}`}
function getEmployeeRecord(id){const custom=getCustomEmployees().find(e=>e.employeeId===id);if(custom)return custom;const e=employees.find(x=>x[1]===id);return e?{name:e[0],employeeId:e[1],department:e[2],position:e[3],location:e[4],status:e[5],company:'ABOMB',hireDate:'2024-01-01',employmentType:'正式任用',manager:'—',email:`${e[1].toLowerCase()}@abomb.com`,phone:'—'}:null}
const approvals=[['leave','病假申請','王思涵','07/21 全天','代理人：無','待審核'],['overtime','加班申請','張育誠','07/20 18:30–21:00','專案上線支援','待審核'],['correction','補卡申請','黃柏翰','07/19 上班卡','裝置定位異常','待審核'],['leave','旅遊假申請','陳冠宇','07/27–07/29','代理人：林怡君','待審核']];
