approvals:()=>{const c=pendingApprovalCounts(),completed=getSharedEvents().filter(e=>e.category==='approval'&&e.status!=='review').length+getAdminApprovalRecords().length;return head('簽核中心','Approvals','集中處理請假、加班與補卡申請',`<button class="secondary-btn" data-bulk>批次審核</button>`)+`<div class="stat-grid">${stat('待審核假件',String(c.leave),c.leave?'即時同步 Employee App':'目前無待審核假件',c.leave?'trend warn':'trend up')}${stat('待審核加班',String(c.overtime),c.overtime?'含 App 新申請':'目前無待審核加班',c.overtime?'trend warn':'trend up')}${stat('待處理補卡',String(c.correction),c.correction?'重大異常優先':'目前無待處理補卡',c.correction?'trend warn':'trend up')}${stat('已完成紀錄',String(completed),'保留審核人與時間')}</div>${panel('待簽核項目',c.total?`共 ${c.total} 件・核准或退回後自動移至下方紀錄`:'所有案件均已處理完成',toolbar('搜尋申請人或項目',`<select class="filter-select"><option>全部類型</option><option>請假</option><option>加班</option><option>補卡</option></select>`)+approvalTable())}${panel('已完成簽核紀錄','永久保留結果、審核人、角色與完成時間',completedApprovalTable())}`},
