function getBenefits(){try{return JSON.parse(localStorage.getItem('bombhr-benefit-policies')||'null')||benefitDefaults}catch(e){return benefitDefaults}}
function getBenefitLeaves(){try{return JSON.parse(localStorage.getItem('bombhr-benefit-leaves')||'null')||benefitLeaveDefaults}catch(e){return benefitLeaveDefaults}}
function benefitPolicyPanel(){const benefits=getBenefits(),leaves=getBenefitLeaves(),enabled=benefits.filter(x=>x.enabled).length,total=benefits.reduce((n,x)=>n+Number(x.amount||0),0);return panel('員工福利主檔','企業可自由新增、編輯、停用或刪除福利；不綁定特定年度',`<div class="benefit-kpis"><div><small>啟用福利項目</small><b>${enabled} 項</b></div><div><small>固定福利金額合計</small><b>NT$ ${total.toLocaleString()}</b></div><div><small>旅遊假最高</small><b>${Math.max(...leaves.map(x=>x.travel))} 天</b></div><div><small>年假最高</small><b>${Math.max(...leaves.map(x=>x.annual))} 天</b></div></div><div class="benefit-tags">${benefits.slice(0,8).map(x=>`<span>${x.name}<b>${x.amount?`NT$ ${x.amount.toLocaleString()}`:'依規則核定'}</b></span>`).join('')}</div>`,`<button class="secondary-btn" data-benefit-manage>管理福利與假別</button>`)}
function getSalaryStructures(){try{return JSON.parse(localStorage.getItem('bombhr-salary-structures')||'null')||salaryStructureDefaults}catch(e){return salaryStructureDefaults}}
function salaryFixedTotal(s){return Number(s.base||0)+Number(s.positionAllowance||0)+Number(s.attendanceBonus||0)+Number(s.seniorityAllowance||0)}
function salaryStructurePanel(){const data=getSalaryStructures(),items=getPayrollItems();return panel('薪資架構與項目主檔','職位固定薪資＋可自訂收入、扣款、加班及雇主提撥規則',`<div class="salary-structure-cards">${data.map(s=>`<div class="salary-role-card"><div><small>POSITION</small><b>${s.position}</b></div><strong>${salaryFixedTotal(s)?`NT$ ${salaryFixedTotal(s).toLocaleString()}`:'尚未設定'}</strong><span>${salaryFixedTotal(s)?'每月固定項目合計':'等待 HR 填寫薪資架構'}</span></div>`).join('')}</div><div class="salary-source-note"><b>目前共 ${items.length} 個可自訂薪資項目</b><span>項目可新增、改名、停用或刪除，不固定限制企業使用方式</span><span>公式項目可連動排班、出勤、簽核及投保資料</span></div>`,`<button class="secondary-btn" data-bank-master>企業銀行主檔</button><button class="secondary-btn" data-salary-structure>編輯完整薪資架構</button>`)}
function salaryStructureModal(){const data=getSalaryStructures();openModal('職位薪資架構主檔','HR 可直接填寫；儲存後，新進員工選擇職位即自動套用',`<div class="salary-editor-wrap"><table class="salary-editor"><thead><tr><th>職位</th><th>底薪</th><th>職務津貼</th><th>全勤獎金</th><th>年資津貼</th><th>固定合計</th><th>計稅</th><th>納入投保薪資</th></tr></thead><tbody>${data.map((s,i)=>`<tr data-salary-row="${i}"><td><input data-field="position" value="${s.position}"></td><td><input data-field="base" type="number" value="${s.base}"></td><td><input data-field="positionAllowance" type="number" value="${s.positionAllowance}"></td><td><input data-field="attendanceBonus" type="number" value="${s.attendanceBonus}"></td><td><input data-field="seniorityAllowance" type="number" value="${s.seniorityAllowance}"></td><td><b data-salary-total>NT$ ${salaryFixedTotal(s).toLocaleString()}</b></td><td><select data-field="taxable"><option ${s.taxable==='是'?'selected':''}>是</option><option ${s.taxable==='否'?'selected':''}>否</option></select></td><td><select data-field="insured"><option ${s.insured==='是'?'selected':''}>是</option><option ${s.insured==='否'?'selected':''}>否</option></select></td></tr>`).join('')}</tbody></table></div><div class="salary-rule-grid"><div><b>固定薪資架構</b><small>依職位自動套用到員工任用資料</small></div><div><b>每月變動項目</b><small>依排班、出勤、加班與扣款結果計算</small></div><div><b>人工覆寫</b><small>個別員工調薪須填寫原因並保留歷程</small></div></div>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="saveSalaryStructure">儲存並套用</button>`);const update=()=>$$('[data-salary-row]').forEach(row=>{const sum=['base','positionAllowance','attendanceBonus','seniorityAllowance'].reduce((n,k)=>n+Number(row.querySelector(`[data-field="${k}"]`).value||0),0);row.querySelector('[data-salary-total]').textContent=`NT$ ${sum.toLocaleString()}`});$$('[data-salary-row] input').forEach(x=>x.oninput=update);$('#saveSalaryStructure').onclick=()=>{const next=$$('[data-salary-row]').map(row=>Object.fromEntries($$('[data-field]',row).map(x=>[x.dataset.field,x.type==='number'?Number(x.value||0):x.value])));localStorage.setItem('bombhr-salary-structures',JSON.stringify(next));closeModal();location.hash='payroll';window.dispatchEvent(new HashChangeEvent('hashchange'));toast('職位薪資架構已儲存，新進員工將自動套用')}}
function employeeOnboardingModal(){const salaries=getSalaryStructures(),leaves=getBenefitLeaves(),employeeId=nextEmployeeId(),today=new Date().toISOString().slice(0,10);openModal('新增員工與任用資料',`預計建立員工編號 ${employeeId}・姓名與員編建立後本人不可修改`,`<div class="employee-form-section"><b>基本資料</b><div class="form-grid"><label class="form-field">員工姓名 *<input id="newEmployeeName" class="form-control" placeholder="例如：陳小華"></label><label class="form-field">員工編號<input id="newEmployeeId" class="form-control" value="${employeeId}" readonly></label><label class="form-field">公司<select id="newEmployeeCompany" class="form-control"><option>ABOMB</option></select></label><label class="form-field">工作據點 *<select id="newEmployeeLocation" class="form-control"><option>台北總部</option><option>台中據點</option><option>高雄據點</option></select></label><label class="form-field">部門 *<select id="newEmployeeDepartment" class="form-control"><option>營運管理部</option><option>人力資源部</option><option>資訊技術部</option><option>財務會計部</option><option>門市營運部</option></select></label><label class="form-field">職位 *<select id="newEmployeePosition" class="form-control"><option value="">請選擇職位</option>${salaries.map(s=>`<option>${s.position}</option>`).join('')}</select></label></div></div><div class="employee-form-section"><b>任用與帳號</b><div class="form-grid"><label class="form-field">到職日 *<input id="newEmployeeHireDate" type="date" class="form-control" value="${today}"></label><label class="form-field">任用類型<select id="newEmployeeType" class="form-control"><option>試用期</option><option>正式任用</option><option>培訓新人</option><option>定期契約</option></select></label><label class="form-field">試用／培訓期間<select id="newEmployeeProbation" class="form-control"><option>3 個月</option><option>2 個月</option><option>1 個月</option><option>7 天</option><option>自訂</option></select></label><label class="form-field">直屬主管<select id="newEmployeeManager" class="form-control"><option>陳冠宇・AB00118</option><option>林怡君・AB00001</option><option>無</option></select></label><label class="form-field">權限群組<select id="newEmployeeRole" class="form-control"><option>一般員工</option><option>部門主管</option><option>據點營運主管</option><option>薪酬財務專員</option></select></label><label class="form-field">帳號狀態<select id="newEmployeeAccount" class="form-control"><option>到職日啟用</option><option>立即啟用</option><option>暫不啟用</option></select></label></div></div><div class="employee-form-section"><b>聯絡資料</b><div class="form-grid"><label class="form-field">公司 Email *<input id="newEmployeeEmail" type="email" class="form-control" placeholder="name@abomb.com"></label><label class="form-field">聯絡電話<input id="newEmployeePhone" class="form-control" placeholder="09xx-xxx-xxx"></label></div></div><div id="salaryAutoPreview" class="salary-auto-preview"><small>選擇職位後，系統會顯示並套用薪資與福利資格。</small></div><p id="employeeFormError" class="form-error"></p>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="saveNewEmployee">建立員工主檔</button>`);const showPreview=()=>{const s=salaries.find(x=>x.position===$('#newEmployeePosition').value),level=$('#newEmployeeType').value==='試用期'||$('#newEmployeeType').value==='培訓新人'?'新進員工':s?.position.includes('經理')?'經理':s?.position.includes('主管')?'主管':'員工',leave=leaves.find(x=>x.level===level);if(!s){$('#salaryAutoPreview').innerHTML='<small>選擇職位後，系統會顯示並套用薪資與福利資格。</small>';return}$('#salaryAutoPreview').innerHTML=`<div><small>職位薪資</small><b>${s.position}</b></div><div><small>底薪＋津貼</small><b>NT$ ${(Number(s.base)+Number(s.positionAllowance)).toLocaleString()}</b></div><div><small>全勤／年資</small><b>NT$ ${(Number(s.attendanceBonus)+Number(s.seniorityAllowance)).toLocaleString()}</b></div><div><small>固定薪資合計</small><strong>NT$ ${salaryFixedTotal(s).toLocaleString()}</strong></div><div><small>${level}假別</small><b>旅遊假 ${leave?.travel||0} 天・年假 ${leave?.annual||0} 天</b></div>`};$('#newEmployeePosition').onchange=showPreview;$('#newEmployeeType').onchange=showPreview;$('#saveNewEmployee').onclick=()=>{const name=$('#newEmployeeName').value.trim(),position=$('#newEmployeePosition').value,email=$('#newEmployeeEmail').value.trim(),salary=salaries.find(x=>x.position===position);if(!name||!position||!email){$('#employeeFormError').textContent='請完整填寫姓名、職位與公司 Email。';return}if(!salaryFixedTotal(salary)){$('#employeeFormError').textContent='此職位尚未設定薪資架構，請先至薪資管理完成設定。';return}const type=$('#newEmployeeType').value,level=type==='試用期'||type==='培訓新人'?'新進員工':position.includes('經理')?'經理':position.includes('主管')?'主管':'員工',leave=leaves.find(x=>x.level===level),record={name,employeeId,company:$('#newEmployeeCompany').value,location:$('#newEmployeeLocation').value,department:$('#newEmployeeDepartment').value,position,hireDate:$('#newEmployeeHireDate').value,employmentType:type,probation:$('#newEmployeeProbation').value,manager:$('#newEmployeeManager').value,roleGroup:$('#newEmployeeRole').value,accountStatus:$('#newEmployeeAccount').value,email,phone:$('#newEmployeePhone').value,status:type==='正式任用'?'在職':type==='培訓新人'?'培訓中':'試用期',salary:{...salary,effectiveDate:$('#newEmployeeHireDate').value},benefitLevel:level,leaveEntitlement:{...leave},createdBy:'林怡君・AB00001',createdAt:new Date().toISOString()};const list=getCustomEmployees();list.push(record);localStorage.setItem('bombhr-custom-employees',JSON.stringify(list));closeModal();location.hash='employees';window.dispatchEvent(new HashChangeEvent('hashchange'));toast(`${name}（${employeeId}）已建立並加入員工名冊`)}}
