function basicSettings(){return panel('企業基本設定','ABOMB',`<div class="form-grid"><label class="form-field">企業顯示名稱<input class="form-control" value="ABOMB"></label><label class="form-field">預設語言<select class="form-control"><option>繁體中文</option><option>English</option></select></label><label class="form-field">主要時區<select class="form-control"><option>Asia/Taipei (UTC+8)</option></select></label><label class="form-field">員工編號政策<select class="form-control"><option>離職後不可重複使用</option></select></label></div>`)}
const scheduleToday=new Date(),scheduleStart=new Date(scheduleToday.getFullYear(),scheduleToday.getMonth()-12,1),scheduleEnd=new Date(scheduleToday.getFullYear(),scheduleToday.getMonth()+11,1);let scheduleCursor=new Date(scheduleToday.getFullYear(),scheduleToday.getMonth(),1),scheduleMode='month';
function monthKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function scheduleMonths(){return Array.from({length:24},(_,i)=>new Date(scheduleStart.getFullYear(),scheduleStart.getMonth()+i,1))}
function scheduleMonthOptions(){return scheduleMonths().map(d=>`<option value="${monthKey(d)}" ${monthKey(d)===monthKey(scheduleCursor)?'selected':''}>${d.getFullYear()} 年 ${d.getMonth()+1} 月</option>`).join('')}
function lunarLabel(date){try{return new Intl.DateTimeFormat('zh-TW-u-ca-chinese',{month:'short',day:'numeric'}).format(date).replace(/\s/g,'')}catch(e){return ''}}
function scheduleCalendarDays(){const y=scheduleCursor.getFullYear(),m=scheduleCursor.getMonth(),first=new Date(y,m,1).getDay(),gridStart=new Date(y,m,1-first);return Array.from({length:42},(_,i)=>{const date=new Date(gridStart.getFullYear(),gridStart.getMonth(),gridStart.getDate()+i),day=date.getDate(),muted=date.getMonth()!==m,isToday=date.getFullYear()===scheduleToday.getFullYear()&&date.getMonth()===scheduleToday.getMonth()&&day===scheduleToday.getDate(),dateKey=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;return `<div class="day ${muted?'muted':''} ${isToday?'today':''}" data-day="${day}" data-date="${dateKey}"><div class="day-head"><b>${day}</b><span class="lunar">${lunarLabel(date)}</span></div>${!muted&&day%3===0?`<span class="shift">早班 08:30–17:30</span>`:''}${!muted&&isToday?'<span class="shift warn">台中缺口 2 人</span>':''}${!muted&&day===27?'<span class="shift warn">主管備註：盤點</span>':''}</div>`}).join('')}
function weekSchedule(){const names=['林怡君','陳冠宇','王思涵','張育誠','黃柏翰'];return `<div class="schedule-week">${names.map((n,i)=>`<div class="week-person"><div class="person"><span class="avatar">${n[0]}</span><b>${n}</b></div>${Array.from({length:7},(_,d)=>`<span class="week-shift ${d>4?'off':''}">${d>4?'休':i%2?'09:00–18:00':'08:30–17:30'}</span>`).join('')}</div>`).join('')}</div>`}
function staffSchedule(){return `<div class="table-wrap"><table><thead><tr><th>員工</th><th>本月排班</th><th>預定工時</th><th>休假</th><th>跨據點</th><th>操作</th></tr></thead><tbody>${employees.map((e,i)=>`<tr><td><div class="person"><span class="avatar">${e[0][0]}</span><div><b>${e[0]}</b><small>${e[1]}</small></div></div></td><td>${20+i%3} 班</td><td>${160+i*4} 小時</td><td>${8+i%2*8} 小時</td><td>${i===1?'台中支援 2 日':'—'}</td><td class="row-actions"><button data-staff-schedule="${e[1]}">查看班表</button></td></tr>`).join('')}</tbody></table></div>`}
function schedulingView(){const historical=scheduleCursor<new Date(scheduleToday.getFullYear(),scheduleToday.getMonth(),1),atStart=monthKey(scheduleCursor)===monthKey(scheduleStart),atEnd=monthKey(scheduleCursor)===monthKey(scheduleEnd),body=scheduleMode==='month'?`<div class="calendar-scroll"><div class="calendar-head"><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span><span>日</span></div><div class="calendar-grid">${scheduleCalendarDays()}</div></div>`:scheduleMode==='week'?weekSchedule():staffSchedule();return head('排班與營運月曆','Scheduling','24 個月快速檢視、農曆、主管備註與跨據點人力支援',`<button class="secondary-btn" data-copy-month ${historical?'disabled':''}>複製上月班表</button><button class="secondary-btn" data-calendar-note ${historical?'disabled':''}>新增主管備註</button><button class="primary-btn" data-add="shift" ${historical?'disabled':''}>新增班別</button>`)+`<div class="schedule-toolbar"><div class="month-nav"><button class="icon-btn" data-schedule-prev ${atStart?'disabled':''}>‹</button><select id="scheduleMonthSelect">${scheduleMonthOptions()}</select><button class="icon-btn" data-schedule-next ${atEnd?'disabled':''}>›</button><button class="secondary-btn" data-schedule-today>回到今天</button></div><div class="schedule-view-switch"><button data-schedule-view="month" class="${scheduleMode==='month'?'active':''}">月</button><button data-schedule-view="week" class="${scheduleMode==='week'?'active':''}">週</button><button data-schedule-view="staff" class="${scheduleMode==='staff'?'active':''}">人員</button></div></div>${historical?'<div class="history-banner">歷史班表為唯讀模式；所有原始班別與異動紀錄永久保留。</div>':''}`+panel(`${scheduleCursor.getFullYear()} 年 ${scheduleCursor.getMonth()+1} 月`,`${historical?'歷史唯讀':'可編輯'}・ABOMB 全公司・快速範圍共 24 個月`,body)}
function refreshScheduling(){location.hash='scheduling';window.dispatchEvent(new HashChangeEvent('hashchange'))}
function bindScheduling(){const shift=delta=>{const d=new Date(scheduleCursor.getFullYear(),scheduleCursor.getMonth()+delta,1);if(d>=scheduleStart&&d<=scheduleEnd){scheduleCursor=d;refreshScheduling()}};$('[data-schedule-prev]')?.addEventListener('click',()=>shift(-1));$('[data-schedule-next]')?.addEventListener('click',()=>shift(1));$('#scheduleMonthSelect')?.addEventListener('change',e=>{const [y,m]=e.target.value.split('-').map(Number);scheduleCursor=new Date(y,m-1,1);refreshScheduling()});$('[data-schedule-today]')?.addEventListener('click',()=>{scheduleCursor=new Date(scheduleToday.getFullYear(),scheduleToday.getMonth(),1);refreshScheduling()});$$('[data-schedule-view]').forEach(b=>b.onclick=()=>{scheduleMode=b.dataset.scheduleView;refreshScheduling()});$('[data-copy-month]')?.addEventListener('click',()=>openModal('複製上月班表',`複製至 ${scheduleCursor.getFullYear()} 年 ${scheduleCursor.getMonth()+1} 月`,`<div class="detail-box"><small>來源月份</small><b>${new Date(scheduleCursor.getFullYear(),scheduleCursor.getMonth()-1,1).getFullYear()} 年 ${new Date(scheduleCursor.getFullYear(),scheduleCursor.getMonth()-1,1).getMonth()+1} 月</b></div><p style="color:var(--muted)">將複製班別、人員配置與主管備註；請假及臨時異常不會被複製。</p>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="copyScheduleConfirm">確認複製</button>`));setTimeout(()=>{if($('#copyScheduleConfirm'))$('#copyScheduleConfirm').onclick=()=>{closeModal();toast('上月班表已複製，尚未發布')}},0);$$('[data-staff-schedule]').forEach(b=>b.onclick=()=>toast(`已開啟 ${b.dataset.staffSchedule} 的個人班表`))}
