 $$('[data-route-go]').forEach(b=>b.onclick=()=>location.hash=b.dataset.routeGo);$$('[data-export]').forEach(b=>b.onclick=()=>toast('Demo：報表已準備匯出'));$$('[data-table-search]').forEach(i=>i.oninput=()=>{$$('[data-search-row]').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(i.value.toLowerCase()))});
 $$('[data-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.add));$$('[data-generic-edit],[data-generic-create]').forEach(b=>b.onclick=()=>openForm('generic'));$$('[data-view-employee]').forEach(b=>b.onclick=()=>employeeModal(b.dataset.viewEmployee,false));$$('[data-edit-employee]').forEach(b=>b.onclick=()=>employeeModal(b.dataset.editEmployee,true));$$('[data-approval]').forEach(b=>b.onclick=()=>{const i=+b.dataset.approval;approvalModal(i);$('#rejectBtn').onclick=()=>{const note=$('#modalBody textarea')?.value||'資料需補充，請重新送出。';closeModal();completeAdminApproval(i,'已退回',note);toast('申請已退回並移至完成紀錄')};$('#approveBtn').onclick=()=>{const note=$('#modalBody textarea')?.value||'';closeModal();completeAdminApproval(i,'已核准',note);toast('申請已核准並移至完成紀錄')}});$$('[data-shared-approval]').forEach(b=>b.onclick=()=>sharedApprovalModal(b.dataset.sharedApproval));
 $$('[data-device-reset]').forEach(b=>b.onclick=()=>confirmModal('解除裝置綁定','解除後，員工需重新完成裝置驗證才能打卡。','確認解除'));$$('[data-save-settings]').forEach(b=>b.onclick=()=>toast('企業設定已儲存並留下稽核紀錄'));$$('[data-calendar-note]').forEach(b=>b.onclick=()=>openForm('note'));$$('[data-bulk]').forEach(b=>b.onclick=()=>toast('請先勾選要批次處理的申請'));
