 makeInteractive($$('.notice-item:not([data-quick-route])'),item=>openModal('公告內容',item.querySelector('b')?.textContent||'重要公告',`<p>${item.querySelector('small')?.textContent||'ABOMB 企業公告'}</p><div class="detail-box"><small>公告說明</small><b>此為後台 Demo 公告內容，可追蹤發布範圍、閱讀率與確認狀態。</b></div>`));
