function setupScope(){const data=[['AB','ABOMB 全公司','總部＋3 個據點'],['TP','台北總部','676 位員工'],['TC','台中據點','318 位員工'],['KH','高雄據點','254 位員工']];const pop=$('#scopePopover');function draw(q=''){ $('#scopeList').innerHTML=data.filter(x=>x.join('').includes(q)).map((x,i)=>`<button class="scope-option ${i===0?'active':''}" data-scope="${x[1]}"><span>${x[0]}</span><div><b>${x[1]}</b><small>${x[2]}</small></div></button>`).join('');$$('[data-scope]').forEach(b=>b.onclick=()=>{$('#scopeLabel').textContent=b.dataset.scope;$('.scope-mini b').textContent=b.dataset.scope;pop.classList.remove('open');toast(`資料範圍已切換為 ${b.dataset.scope}`)})}draw();$('#scopeBtn').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();pop.style.top=r.bottom+8+'px';pop.style.left=Math.max(10,r.left)+'px';pop.classList.toggle('open')};$('#scopeSearch').oninput=e=>draw(e.target.value)}
function setupNotifications(){const drawer=$('#notificationDrawer'),mask=$('#drawerMask');const open=()=>{drawer.classList.add('open');mask.classList.add('open');drawDrawer('notify')},close=()=>{drawer.classList.remove('open');mask.classList.remove('open')};$('#notificationBtn').onclick=open;mask.onclick=close;$('[data-close-drawer]').onclick=close;$$('[data-drawer-tab]').forEach(b=>b.onclick=()=>{$$('[data-drawer-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');drawDrawer(b.dataset.drawerTab)});$('#soundSwitch').onchange=e=>toast(e.target.checked?'重要事件音效已開啟':'重要事件音效已關閉')}
const demoTasks=[{id:'attendance-check',route:'attendance',title:'完成今日出勤異常核對'},{id:'leave-review',route:'approvals',title:'審核 12 件請假申請'},{id:'support-list',route:'scheduling',title:'確認台中跨店支援名單'}];
function getCompletedTasks(){try{return JSON.parse(localStorage.getItem('bombhr-completed-tasks')||'[]')}catch(e){return []}}
function taskDrawerHtml(){const completed=getCompletedTasks(),pending=demoTasks.filter(t=>!completed.some(c=>c.id===t.id)),done=completed.filter(c=>demoTasks.some(t=>t.id===c.id));return `<div class="task-section-head"><b>待確認</b><small>${pending.length} 件</small></div><div class="task-list">${pending.length?pending.map(t=>`<div class="task-item task-confirm-row" data-task-id="${t.id}"><label><input type="checkbox"><span>${t.title}</span></label><button class="task-confirm-btn" data-confirm-task="${t.id}" disabled>確認完成</button><button class="task-route-btn" data-task-route="${t.route}" aria-label="前往處理">→</button></div>`).join(''):'<div class="task-empty">目前沒有待確認事項</div>'}</div>${pending.length?`<div class="task-bulk-bar"><label><input id="selectAllTasks" type="checkbox"> 全選</label><button id="confirmSelectedTasks" class="primary-btn" disabled>確認選取項目已完成</button></div>`:''}<details class="completed-tasks" ${done.length?'':'hidden'}><summary>已完成紀錄（${done.length}）</summary>${done.map(c=>`<div class="completed-task"><span>✓</span><div><b>${c.title}</b><small>${c.reviewer}・${c.completedAt}</small></div></div>`).join('')}</details>`}
function drawDrawer(type){const body=$('#drawerBody');body.innerHTML=type==='notify'?`<div class="notice-list"><div class="notice-item" data-quick-route="scheduling"><i>!</i><div><b>台中據點臨時人力缺口</b><small>2 分鐘前・需要跨店支援</small></div></div><div class="notice-item" data-quick-route="approvals"><i>✓</i><div><b>王思涵提交事假申請</b><small>12 分鐘前・等待審核</small></div></div><div class="notice-item" data-quick-route="attendance"><i>◷</i><div><b>5 位員工裝置定位異常</b><small>25 分鐘前・重大異常</small></div></div></div>`:taskDrawerHtml();$$('[data-quick-route]',body).forEach(item=>item.onclick=()=>{location.hash=item.dataset.quickRoute;$('#notificationDrawer').classList.remove('open');$('#drawerMask').classList.remove('open');toast('已開啟對應處理頁面')});const refreshBulk=()=>{const inputs=$$('[data-task-id] input',body),selected=inputs.filter(x=>x.checked);if($('#confirmSelectedTasks'))$('#confirmSelectedTasks').disabled=!selected.length;if($('#selectAllTasks'))$('#selectAllTasks').checked=inputs.length>0&&selected.length===inputs.length};$$('[data-task-id] input',body).forEach(input=>input.onchange=()=>{const row=input.closest('[data-task-id]'),button=row.querySelector('[data-confirm-task]');row.classList.toggle('ready',input.checked);button.disabled=!input.checked;refreshBulk()});$('#selectAllTasks')?.addEventListener('change',e=>{$$('[data-task-id] input',body).forEach(input=>{input.checked=e.target.checked;input.dispatchEvent(new Event('change'))})});$('#confirmSelectedTasks')?.addEventListener('click',()=>confirmTasks($$('[data-task-id] input:checked',body).map(x=>x.closest('[data-task-id]').dataset.taskId)));$$('[data-task-route]',body).forEach(button=>button.onclick=()=>{location.hash=button.dataset.taskRoute;$('#notificationDrawer').classList.remove('open');$('#drawerMask').classList.remove('open');toast('已開啟待辦處理頁面')});$$('[data-confirm-task]',body).forEach(button=>button.onclick=()=>confirmTask(button.dataset.confirmTask))}
function confirmTask(id){const task=demoTasks.find(t=>t.id===id);if(!task)return;openModal('確認完成待辦',task.title,`<div class="detail-box"><small>完成者</small><b>林怡君・AB00001・HR 系統管理者</b></div><p style="color:var(--muted)">確認後會移出待辦清單，並保留完成時間與登入身分紀錄。</p>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="completeTaskBtn">確認已完成</button>`);$('#completeTaskBtn').onclick=()=>{const completed=getCompletedTasks();if(!completed.some(c=>c.id===id))completed.unshift({...task,reviewer:'林怡君（AB00001）',completedAt:new Date().toLocaleString('zh-TW',{hour12:false})});localStorage.setItem('bombhr-completed-tasks',JSON.stringify(completed));closeModal();drawDrawer('task');toast('待辦已確認完成，紀錄已保留')}}
function confirmTasks(ids){if(!ids.length)return;openModal('批次確認完成',`共選取 ${ids.length} 件待辦`,`<div class="detail-box"><small>確認人</small><b>林怡君・AB00001・HR 系統管理者</b></div><p style="color:var(--muted)">確認後，選取項目會移至已完成紀錄並保留時間戳記。</p>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="completeSelectedTasks">確認全部完成</button>`);$('#completeSelectedTasks').onclick=()=>{const completed=getCompletedTasks(),time=new Date().toLocaleString('zh-TW',{hour12:false});ids.forEach(id=>{const task=demoTasks.find(t=>t.id===id);if(task&&!completed.some(c=>c.id===id))completed.unshift({...task,reviewer:'林怡君（AB00001）',completedAt:time})});localStorage.setItem('bombhr-completed-tasks',JSON.stringify(completed));closeModal();drawDrawer('task');toast(`已確認完成 ${ids.length} 件待辦`)}}
function setupSearch(){const cmd=$('#command'),input=$('#globalSearch');window.openSearch=()=>{cmd.classList.add('open');input.focus();search('')};$('#searchBtn').onclick=openSearch;cmd.onclick=e=>{if(e.target===cmd)cmd.classList.remove('open')};input.oninput=e=>search(e.target.value);function search(q){const items=[['營運總覽','dashboard'],['員工人事主檔','employees'],['林怡君 AB00001','employees'],['出勤與裝置管理','attendance'],['簽核中心','approvals'],['角色與權限群組','permissions'],['企業系統設定','settings']].filter(x=>x[0].includes(q));$('#searchResults').innerHTML=items.map(x=>`<button class="search-result" data-search-route="${x[1]}"><span>${x[0]}</span><small>開啟 →</small></button>`).join('');$$('[data-search-route]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.searchRoute;cmd.classList.remove('open')})}}
function setupProfile(){const pop=$('#profilePopover');$('#profileBtn').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();pop.style.top=r.bottom+8+'px';pop.style.right='14px';pop.classList.toggle('open')};$$('[data-profile]').forEach(b=>b.onclick=()=>{pop.classList.remove('open');openModal(b.dataset.profile==='account'?'我的帳號':'權限資料範圍','林怡君・AB00001',b.dataset.profile==='account'?'<div class="detail-grid"><div class="detail-box"><small>角色</small><b>HR 系統管理者</b></div><div class="detail-box"><small>登入方式</small><b>員工編號</b></div></div>':'<div class="detail-box"><small>目前範圍</small><b>ABOMB 全公司・所有據點與部門</b></div>')})}
document.addEventListener('change',e=>{if(e.target.id!=='selectAllTasks')return;const checked=e.target.checked;setTimeout(()=>{const body=$('#drawerBody');$$('[data-task-id] input',body).forEach(input=>{input.checked=checked;const row=input.closest('[data-task-id]');row.classList.toggle('ready',checked);row.querySelector('[data-confirm-task]').disabled=!checked});const bulk=$('#confirmSelectedTasks');if(bulk)bulk.disabled=!checked},0)},true);
function enhanceEmployeeBankFields(){const preview=$('#salaryAutoPreview');if(!preview)return;preview.insertAdjacentHTML('beforebegin',`<div class="employee-form-section bank-section"><b>薪資轉帳銀行資料</b><div class="form-grid"><label class="form-field">銀行名稱 *<select id="newEmployeeBank" class="form-control"><option value="">請選擇銀行</option><option>國泰世華銀行</option><option>中國信託銀行</option><option>台新銀行</option><option>玉山銀行</option><option>第一銀行</option><option>其他銀行</option></select></label><label class="form-field">分行名稱 *<input id="newEmployeeBankBranch" class="form-control" placeholder="例如：台北分行"></label><label class="form-field">銀行戶名 *<input id="newEmployeeAccountName" class="form-control" placeholder="須與員工本人姓名相符"></label><label class="form-field">銀行帳號 *<input id="newEmployeeBankAccount" class="form-control" inputmode="numeric" autocomplete="off" placeholder="請輸入完整帳號"></label></div><label class="bankbook-upload">上傳存摺封面或銀行帳戶證明照片 *<small>JPG、PNG、WEBP；Demo 上限 1.2 MB</small><input id="newEmployeeBankbook" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="bankbookPreview" class="bankbook-preview"><small>尚未選擇銀行帳戶照片</small></div></div>`);let bankbookData='',bankbookName='';$('#newEmployeeBankbook').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>1258291){$('#employeeFormError').textContent='銀行帳戶照片超過 1.2 MB，請壓縮後重新上傳。';e.target.value='';return}const reader=new FileReader();reader.onload=()=>{bankbookData=reader.result;bankbookName=file.name;$('#bankbookPreview').innerHTML=`<img src="${bankbookData}" alt="銀行帳戶照片預覽"><div><b>${file.name}</b><small>${Math.ceil(file.size/1024)} KB・已準備儲存</small></div>`};reader.readAsDataURL(file)};const button=$('#saveNewEmployee'),original=button.onclick;button.onclick=()=>{const bank=$('#newEmployeeBank').value,branch=$('#newEmployeeBankBranch').value.trim(),accountName=$('#newEmployeeAccountName').value.trim(),account=$('#newEmployeeBankAccount').value.replace(/\s/g,'');if(!bank||!branch||!accountName||!account||!bankbookData){$('#employeeFormError').textContent='請完整填寫銀行、分行、戶名、帳號並上傳銀行帳戶照片。';return}if(!/^\d{8,20}$/.test(account)){$('#employeeFormError').textContent='銀行帳號應為 8–20 位數字，請重新確認。';return}const before=getCustomEmployees().length;original();const list=getCustomEmployees();if(list.length===before+1){const record=list[list.length-1];record.bank={bank,branch,accountName,account,bankbookName,bankbookData,verified:false,updatedAt:new Date().toISOString()};localStorage.setItem('bombhr-custom-employees',JSON.stringify(list))}}}
function enhanceEmployeeBankDetails(id){const e=getEmployeeRecord(id);if(!e?.bank||!$('#modalBody'))return;const account=e.bank.account||'',masked=account.length>5?`${account.slice(0,3)}•••••${account.slice(-3)}`:'••••••••';$('#modalBody').insertAdjacentHTML('beforeend',`<div class="bank-detail-card"><div><small>薪資轉帳銀行</small><b>${e.bank.bank}・${e.bank.branch}</b></div><div><small>戶名</small><b>${e.bank.accountName}</b></div><div><small>帳號（預設遮罩）</small><b id="maskedBankAccount">${masked}</b></div><button class="secondary-btn" data-reveal-bank="${account}">顯示完整帳號</button>${e.bank.bankbookData?`<a href="${e.bank.bankbookData}" target="_blank" rel="noopener"><img src="${e.bank.bankbookData}" alt="存摺或銀行帳戶證明"><span>查看銀行帳戶照片</span></a>`:''}</div>`);$('[data-reveal-bank]')?.addEventListener('click',event=>{const b=event.currentTarget;if(b.dataset.visible){$('#maskedBankAccount').textContent=masked;b.textContent='顯示完整帳號';delete b.dataset.visible}else{$('#maskedBankAccount').textContent=b.dataset.revealBank;b.textContent='隱藏完整帳號';b.dataset.visible='1'}})}
document.addEventListener('click',e=>{const view=e.target.closest('[data-view-employee],[data-edit-employee]');if(view)setTimeout(()=>enhanceEmployeeBankDetails(view.dataset.viewEmployee||view.dataset.editEmployee),0)},true);
function populateEnterpriseBankSelect(){const select=$('#newEmployeeBank');if(!select)return;select.innerHTML='<option value="">請選擇企業銀行</option>'+getEnterpriseBanks().filter(x=>x.active).map(x=>`<option value="${x.name}" data-branch="${x.branch}">${x.code}・${x.name}（${x.branch}）</option>`).join('');select.onchange=()=>{const option=select.selectedOptions[0];if(option?.dataset.branch)$('#newEmployeeBankBranch').value=option.dataset.branch}}
function enterpriseBankModal(){const draw=()=>{const banks=getEnterpriseBanks();openModal('企業銀行主檔','新增公司可使用的薪轉與付款銀行；員工建檔時直接選用',`<div class="bank-master-list">${banks.map((b,i)=>`<div class="bank-master-row"><span>${b.code}</span><div><b>${b.name}</b><small>${b.branch}・${b.purpose}</small></div>${badge(b.active?'啟用':'停用')}<button data-remove-bank="${i}">移除</button></div>`).join('')}</div><div class="bank-add-form"><b>新增銀行</b><div class="form-grid"><label class="form-field">銀行代碼 *<input id="bankMasterCode" class="form-control" maxlength="3" placeholder="例如：004"></label><label class="form-field">銀行名稱 *<input id="bankMasterName" class="form-control" placeholder="例如：臺灣銀行"></label><label class="form-field">分行名稱 *<input id="bankMasterBranch" class="form-control" placeholder="例如：台北分行"></label><label class="form-field">用途<select id="bankMasterPurpose" class="form-control"><option>員工薪資轉帳</option><option>企業付款</option><option>備用薪轉銀行</option></select></label></div><p id="bankMasterError" class="form-error"></p></div>`,`<button class="secondary-btn" data-modal-close>關閉</button><button class="primary-btn" id="addEnterpriseBank">新增銀行</button>`);$$('[data-remove-bank]').forEach(b=>b.onclick=()=>{const next=getEnterpriseBanks();next.splice(+b.dataset.removeBank,1);saveEnterpriseBanks(next);draw();toast('銀行已從企業主檔移除')});$('#addEnterpriseBank').onclick=()=>{const code=$('#bankMasterCode').value.trim(),name=$('#bankMasterName').value.trim(),branch=$('#bankMasterBranch').value.trim(),purpose=$('#bankMasterPurpose').value;if(!/^\d{3}$/.test(code)||!name||!branch){$('#bankMasterError').textContent='請填寫3位銀行代碼、銀行名稱與分行。';return}const next=getEnterpriseBanks();if(next.some(x=>x.code===code&&x.branch===branch)){$('#bankMasterError').textContent='相同銀行代碼與分行已存在。';return}next.push({code,name,branch,purpose,active:true});saveEnterpriseBanks(next);draw();toast(`${name}已新增至企業銀行主檔`)}};draw()}
function enhanceEmployeePhotoFields(){const section=$('.employee-form-section');if(!section)return;section.querySelector('b').insertAdjacentHTML('afterend',`<div class="employee-photo-upload"><div id="employeePhotoPreview" class="employee-photo-preview">照</div><label>上傳員工大頭照<small>後台與 Employee App 共用同一張照片</small><input id="newEmployeePhoto" type="file" accept="image/jpeg,image/png,image/webp"></label></div>`);let photoData='',photoName='';$('#newEmployeePhoto').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>1258291){$('#employeeFormError').textContent='大頭照超過 1.2 MB，請壓縮後重新上傳。';return}const reader=new FileReader();reader.onload=()=>{photoData=reader.result;photoName=file.name;$('#employeePhotoPreview').innerHTML=`<img src="${photoData}" alt="員工大頭照預覽">`};reader.readAsDataURL(file)};const button=$('#saveNewEmployee'),original=button.onclick;button.onclick=()=>{const id=$('#newEmployeeId').value,before=getCustomEmployees().length;original();if(photoData&&getCustomEmployees().length===before+1){const list=getCustomEmployees(),record=list[list.length-1];record.profilePhoto={name:photoName,data:photoData,updatedAt:new Date().toISOString(),source:'Enterprise HR Admin'};localStorage.setItem('bombhr-custom-employees',JSON.stringify(list));const photos=getProfilePhotos();photos[id]=photoData;localStorage.setItem('bombhr-employee-profile-photos',JSON.stringify(photos));window.dispatchEvent(new CustomEvent('bombhr-profile-photo-update',{detail:{employeeId:id}}))}}}
function enhanceEmployeeProfilePhotoDetails(id){const photo=getProfilePhotos()[id],banner=$('.employee-profile-banner .avatar');if(photo&&banner)banner.innerHTML=`<img src="${photo}" alt="員工大頭照">`}
document.addEventListener('click',e=>{const view=e.target.closest('[data-view-employee],[data-edit-employee]');if(view)setTimeout(()=>enhanceEmployeeProfilePhotoDetails(view.dataset.viewEmployee||view.dataset.editEmployee),0)},true);
window.addEventListener('bombhr-profile-photo-update',()=>{if(location.hash==='#employees')window.dispatchEvent(new HashChangeEvent('hashchange'))});
function benefitManageModalV2(){let draft=getBenefits().map(x=>({...x})),leaves=getBenefitLeaves().map(x=>({...x}));const readDraft=()=>{if(!$('[data-benefit-row]'))return;draft=$$('[data-benefit-row]').map(row=>{const get=f=>row.querySelector(`[data-benefit-field="${f}"]`);return {enabled:get('enabled').checked,category:get('category').value,name:get('name').value.trim(),amount:Number(get('amount').value||0),rule:get('rule').value.trim()}});leaves=$$('[data-leave-row]').map((row,i)=>({level:leaves[i].level,travel:Number(row.querySelector('[data-leave-field="travel"]').value||0),annual:Number(row.querySelector('[data-leave-field="annual"]').value||0)}))};const draw=()=>{openModal('員工福利主檔','不綁定年度；HR 可新增、編輯、停用或刪除任何福利項目',`<div class="benefit-editor-actions"><span>目前 ${draft.length} 個福利項目</span><button class="secondary-btn" id="addBenefitRow">＋ 新增福利項目</button></div><div class="benefit-editor-wrap"><table class="benefit-editor"><thead><tr><th>啟用</th><th>分類</th><th>福利名稱／關係</th><th>金額</th><th>發放與申請規則</th><th>操作</th></tr></thead><tbody>${draft.map((b,i)=>`<tr data-benefit-row="${i}"><td><input data-benefit-field="enabled" type="checkbox" ${b.enabled?'checked':''}></td><td><select data-benefit-field="category"><option ${b.category==='節慶／生活'?'selected':''}>節慶／生活</option><option ${b.category==='婚喪喜慶'?'selected':''}>婚喪喜慶</option><option ${b.category==='喪葬補助'?'selected':''}>喪葬補助</option><option ${b.category==='健康照護'?'selected':''}>健康照護</option><option ${b.category==='其他福利'?'selected':''}>其他福利</option></select></td><td><input data-benefit-field="name" value="${b.name}"></td><td><input data-benefit-field="amount" type="number" min="0" value="${b.amount}"></td><td><input data-benefit-field="rule" value="${b.rule}"></td><td><button class="benefit-delete-btn" data-delete-benefit="${i}">刪除</button></td></tr>`).join('')}</tbody></table></div><h4 class="benefit-subtitle">假別資格與基準天數</h4><div class="leave-entitlement-grid">${leaves.map((l,i)=>`<div data-leave-row="${i}"><b>${l.level}</b><label>旅遊假<input data-leave-field="travel" type="number" min="0" value="${l.travel}"> 天</label><label>年假<input data-leave-field="annual" type="number" min="0" value="${l.annual}"> 天</label></div>`).join('')}</div><div class="policy-note">福利主檔沒有年度限制；若制度需要生效期間，正式系統可為單一福利設定開始日與結束日。</div>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="saveBenefitV2">儲存福利主檔</button>`);$('#addBenefitRow').onclick=()=>{readDraft();draft.push({category:'其他福利',name:'新福利項目',amount:0,rule:'請輸入適用條件與發放規則',enabled:true});draw();toast('已新增一列，請填寫福利內容')};$$('[data-delete-benefit]').forEach(b=>b.onclick=()=>{readDraft();draft.splice(+b.dataset.deleteBenefit,1);draw();toast('福利項目已刪除')});$('#saveBenefitV2').onclick=()=>{readDraft();if(draft.some(x=>!x.name)){$('#modalSubtitle').textContent='福利名稱不可空白，請完成後再儲存';return}localStorage.setItem('bombhr-benefit-policies',JSON.stringify(draft));localStorage.setItem('bombhr-benefit-leaves',JSON.stringify(leaves));closeModal();location.hash='payroll';window.dispatchEvent(new HashChangeEvent('hashchange'));toast('員工福利主檔已儲存')}};draw()}
function salaryStructureModalV2(){const positions=getSalaryStructures().map(x=>x.position);let items=getPayrollItems().map(x=>({...x,amounts:{...x.amounts}}));const read=()=>{if(!$('[data-payroll-item-row]'))return;items=$$('[data-payroll-item-row]').map(row=>{const field=n=>row.querySelector(`[data-payroll-field="${n}"]`);return {name:field('name').value.trim(),category:field('category').value,method:field('method').value.trim(),source:field('source').value.trim(),taxable:field('taxable').checked,insured:field('insured').checked,active:field('active').checked,amounts:Object.fromEntries(positions.map(p=>[p,Number(row.querySelector(`[data-position="${p}"]`).value||0)]))}})};const draw=()=>{openModal('完整薪資架構與項目主檔','所有收入、津貼、獎金、加班、扣款與提撥項目皆可新增、編輯或刪除',`<div class="payroll-item-summary"><div><small>薪資項目</small><b>${items.length} 項</b></div><div><small>收入／津貼</small><b>${items.filter(x=>!x.category.includes('扣款')&&!x.category.includes('提撥')).length} 項</b></div><div><small>扣款／提撥</small><b>${items.filter(x=>x.category.includes('扣款')||x.category.includes('提撥')).length} 項</b></div><button class="primary-btn" id="addPayrollItem">＋ 新增薪資項目</button></div><div class="payroll-item-wrap"><table class="payroll-item-table"><thead><tr><th>啟用</th><th>薪資項目</th><th>類型</th><th>計算方式</th><th>資料來源</th>${positions.map(p=>`<th>${p}<small>固定／基準金額</small></th>`).join('')}<th>計稅</th><th>投保薪資</th><th>操作</th></tr></thead><tbody>${items.map((item,i)=>`<tr data-payroll-item-row="${i}"><td><input data-payroll-field="active" type="checkbox" ${item.active?'checked':''}></td><td><input data-payroll-field="name" value="${item.name}"></td><td><select data-payroll-field="category">${['固定收入','變動收入','津貼','獎金','其他收入','法定扣款','其他扣款','雇主提撥'].map(c=>`<option ${item.category===c?'selected':''}>${c}</option>`).join('')}</select></td><td><input data-payroll-field="method" value="${item.method}"></td><td><input data-payroll-field="source" value="${item.source}"></td>${positions.map(p=>`<td><input data-position="${p}" type="number" value="${item.amounts?.[p]||0}"></td>`).join('')}<td><input data-payroll-field="taxable" type="checkbox" ${item.taxable?'checked':''}></td><td><input data-payroll-field="insured" type="checkbox" ${item.insured?'checked':''}></td><td><button class="payroll-item-delete" data-delete-payroll-item="${i}">刪除</button></td></tr>`).join('')}</tbody></table></div><div class="payroll-item-legend"><span><i class="income"></i>收入、津貼、獎金</span><span><i class="deduction"></i>法定及其他扣款</span><span><i class="employer"></i>雇主提撥，不列入員工實領</span></div><div class="policy-note">固定金額會在員工選擇職位時自動帶入；公式型項目則於每月依排班、出勤、簽核或投保級距計算。匯支與現支屬於付款分配，不列為薪資項目。</div>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="savePayrollItems">儲存完整薪資架構</button>`);$('#addPayrollItem').onclick=()=>{read();items.push({name:'新薪資項目',category:'津貼',method:'固定金額',source:'HR 手動設定',taxable:true,insured:false,active:true,amounts:Object.fromEntries(positions.map(p=>[p,0]))});draw();toast('已新增一列薪資項目')};$$('[data-delete-payroll-item]').forEach(b=>b.onclick=()=>{read();items.splice(+b.dataset.deletePayrollItem,1);draw();toast('薪資項目已刪除')});$('#savePayrollItems').onclick=()=>{read();if(items.some(x=>!x.name)){$('#modalSubtitle').textContent='薪資項目名稱不可空白';return}savePayrollItems(items);const structures=getSalaryStructures();const fixedMap={base:'底薪',positionAllowance:'職務津貼',attendanceBonus:'全勤獎金',seniorityAllowance:'年資津貼'};structures.forEach(s=>Object.entries(fixedMap).forEach(([field,name])=>{const item=items.find(x=>x.name===name);if(item)s[field]=Number(item.amounts?.[s.position]||0)}));localStorage.setItem('bombhr-salary-structures',JSON.stringify(structures));closeModal();location.hash='payroll';window.dispatchEvent(new HashChangeEvent('hashchange'));toast('完整薪資架構與項目主檔已儲存')}};draw()}
